{
  "PROP-attendanceze-inv-003": {
    "property_id": "PROP-attendanceze-inv-003",
    "text": "OAuth client_secret must not be exposed in client-side bundles or browser-accessible code.",
    "type": "invariant",
    "assertion": "forall file in client_bundle: !contains(file, OAUTH_CLIENT_SECRET)",
    "severity": "CRITICAL",
    "covers": "SG-006",
    "reachability": {
      "classification": "external-reachable",
      "entry_points": [
        "HTTP"
      ],
      "attacker_controlled": true,
      "bug_bounty_scope": "in-scope"
    },
    "exploitability": "external-attack",
    "code_scope": {
      "locations": [
        {
          "file": "src/app/oauth/token/route.ts",
          "symbol": "POST",
          "line_range": {
            "start": 17,
            "end": 67
          },
          "role": "primary",
          "note": "Token endpoint correctly receives client_secret via formData() (server-side POST body), not URL. Validates against bcrypt hash."
        },
        {
          "file": "src/app/api/admin/oauth/clients/route.ts",
          "symbol": "POST",
          "line_range": {
            "start": 10,
            "end": 70
          },
          "role": "related",
          "note": "Creates new OAuth clients and returns plain-text client_secret once in response body (line 68). Only hash is stored in DB."
        },
        {
          "file": "src/components/dashboard/admin/OAuthClientForm.tsx",
          "symbol": "OAuthClientForm",
          "line_range": {
            "start": 22,
            "end": 187
          },
          "role": "related",
          "note": "Client-side component ('use client') that receives and displays client_secret from API response in a dialog. Secret is not in the bundle but is sent to browser DOM on creation."
        }
      ],
      "resolution_status": "resolved",
      "resolution_method": "grep_fallback"
    }
  }
}
